view.renderCustomize:
function renderCustomize(opts) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Customize dialog requires showEliDialog", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _sortByOrder(a, b) { return a.order - b.order; }

  function _buildBody() {
    var allTiles = opts.getVisibleTools();
    var pinState = opts.getPinState();
    var pinnedSet = pinState.pinnedSet;
    var pinnedOrder = pinState.pinnedOrder;
    var pinnedTiles = allTiles.filter(function (t) { return pinnedSet[t.catalogId]; });
    if (pinnedOrder && pinnedOrder.length) {
      var idxByCat = {};
      pinnedOrder.forEach(function (id, i) { idxByCat[id] = i; });
      pinnedTiles.sort(function (a, b) {
        if (a.core !== b.core) return a.core ? -1 : 1;
        var ai = idxByCat[a.catalogId];
        var bi = idxByCat[b.catalogId];
        if (typeof ai === "number" && typeof bi === "number") return ai - bi;
        if (typeof ai === "number") return -1;
        if (typeof bi === "number") return 1;
        return _sortByOrder(a, b);
      });
    } else {
      pinnedTiles.sort(function (a, b) {
        if (a.core !== b.core) return a.core ? -1 : 1;
        return _sortByOrder(a, b);
      });
    }
    var availableTiles = allTiles.filter(function (t) { return !pinnedSet[t.catalogId]; });
    var grouped = {};
    availableTiles.forEach(function (t) {
      var cat = t.category || "Tools";
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(t);
    });
    var groupKeys = Object.keys(grouped).sort();
    groupKeys.forEach(function (k) {
      grouped[k].sort(function (a, b) { return String(a.title).localeCompare(String(b.title)); });
    });

    var html = '<div class="_eli3_customize_body">';
    html += '<div class="_eli3_customize_section">';
    html += '<div class="_eli3_customize_subtitle">Installed apps</div>';
    html += '<div class="_eli3_customize_list">';
    if (pinnedTiles.length) {
      pinnedTiles.forEach(function (t) {
        var isCore = !!t.core;
        html +=
          '<div class="_eli3_customize_item _eli3_customize_item_pinned' + (isCore ? " _eli3_customize_item_core" : "") + '" data-cat-id="' + _esc(t.catalogId) + '">' +
            '<div class="_eli3_customize_icon">' + _esc(t.icon || "🛠️") + '</div>' +
            '<div class="_eli3_customize_meta">' +
              '<div class="_eli3_customize_name">' + _esc(t.title) +
                (isCore ? ' <span class="_eli3_customize_corebadge">CORE</span>' : '') +
              '</div>' +
            '</div>' +
            '<div class="_eli3_customize_actions">' +
              (isCore
                ? '<span class="_eli3_customize_locked">LOCKED</span>'
                : (
                    '<button type="button" class="_eli3_customize_btn" data-act="up"   title="Move up">↑</button>' +
                    '<button type="button" class="_eli3_customize_btn" data-act="down" title="Move down">↓</button>' +
                    '<button type="button" class="_eli3_customize_btn _eli3_customize_btn_remove" data-act="remove" title="Remove">✕</button>'
                  )
              ) +
            '</div>' +
          '</div>';
      });
    } else {
      html += '<div class="_eli3_customize_empty">No apps pinned.</div>';
    }
    html += '</div></div>';

    html += '<div class="_eli3_customize_section">';
    html += '<div class="_eli3_customize_subtitle">Available apps</div>';
    html += '<div class="_eli3_customize_list _eli3_customize_list_avail">';
    if (groupKeys.length) {
      groupKeys.forEach(function (cat) {
        html += '<div class="_eli3_customize_catheader">' + _esc(cat) + '</div>';
        grouped[cat].forEach(function (t) {
          html +=
            '<div class="_eli3_customize_item _eli3_customize_item_avail" data-cat-id="' + _esc(t.catalogId) + '" data-act="add" title="' + _esc(t.desc || t.title) + '">' +
              '<div class="_eli3_customize_icon">' + _esc(t.icon || "🛠️") + '</div>' +
              '<div class="_eli3_customize_meta">' +
                '<div class="_eli3_customize_name">' + _esc(t.title) + '</div>' +
                (t.desc ? '<div class="_eli3_customize_desc">' + _esc(t.desc) + '</div>' : '') +
              '</div>' +
              '<div class="_eli3_customize_actions">' +
                '<button type="button" class="_eli3_customize_btn _eli3_customize_btn_add" data-act="add" title="Pin">+</button>' +
              '</div>' +
            '</div>';
        });
      });
    } else {
      html += '<div class="_eli3_customize_empty">All installed apps are pinned.</div>';
    }
    html += '</div></div>';

    html += '<div class="_eli3_customize_resetrow">' +
      '<button type="button" class="_eli3_customize_reset">Reset to default</button>' +
    '</div>';
    html += '</div>';
    return html;
  }

  function _wireBodyHandlers(overlay) {
    Array.prototype.forEach.call(overlay.querySelectorAll("._eli3_customize_item_pinned ._eli3_customize_btn"), function (btn) {
      btn.onclick = function (ev) {
        ev.stopPropagation();
        var item = btn.closest("._eli3_customize_item");
        if (!item) return;
        var catId = item.getAttribute("data-cat-id");
        var act = btn.getAttribute("data-act");
        if (act === "up") opts.movePin(catId, -1);
        else if (act === "down") opts.movePin(catId, 1);
        else if (act === "remove") opts.unpin(catId);
        _rerender(overlay);
      };
    });
    Array.prototype.forEach.call(overlay.querySelectorAll("._eli3_customize_item_avail"), function (row) {
      row.onclick = function (ev) {
        ev.stopPropagation();
        var catId = row.getAttribute("data-cat-id");
        if (!catId) return;
        opts.pin(catId);
        _rerender(overlay);
      };
    });
    var resetBtn = overlay.querySelector("._eli3_customize_reset");
    if (resetBtn) resetBtn.onclick = function (ev) {
      ev.stopPropagation();
      opts.resetPins();
      _rerender(overlay);
    };
  }
  function _rerender(overlay) {
    var desc = overlay.querySelector(".eli-dialog-desc");
    if (!desc) return;
    desc.innerHTML =
      '<p class="_eli3_customize_intro">Pin the apps you use most. Reorder with ↑ / ↓. Core apps stay locked at the top.</p>' +
      _buildBody();
    _wireBodyHandlers(overlay);
  }

  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_customize_dialog _eli3_dialog_wide",
    icon: "⚙️",
    title: "Customize Dashboard",
    body:
      '<p class="_eli3_customize_intro">Pin the apps you use most. Reorder with ↑ / ↓. Core apps stay locked at the top.</p>' +
      _buildBody(),
    secondary: { label: "Done" },
    onMount: function (overlay) { _wireBodyHandlers(overlay); },
  });
}


// ─── Help / About / Debug Console tabbed dialog ──────────────────────
// 2026-05-13 rewrite — replaces the old Help/Contact/Console trio:
//   - Help    → "Ask ELI AI" + bug/improvement submission + announcements
//   - About   → developer credit + system info (no buttons)
//   - Debug   → unchanged event log viewer (power-user surface)
// All three tabs share a fixed body height so switching tabs doesn't
// reflow the dialog. Originally extracted from kernel _tabbedDialog
// in Batch 4 (2026-05-11); per-tab content here is fresh.
// opts: { initialTab?: "help"|"about"|"console" }

view.renderTabbedDialog:
function renderTabbedDialog(opts) {
  opts = opts || {};
  var TABS = [
    { id: "help",    label: "Help",  build: _buildHelpTab },
    { id: "about",   label: "About", build: _buildAboutTab },
    { id: "console", label: "Debug", build: _buildConsoleTab },
  ];
  var activeId = opts.initialTab && TABS.some(function (t) { return t.id === opts.initialTab; }) ? opts.initialTab : "help";
  var unsubscribers = [];
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function _activate(id, panel, dialog) {
    activeId = id;
    var btns = dialog.querySelectorAll("._eli3_tab");
    Array.prototype.slice.call(btns).forEach(function (btn) {
      var matches = btn.getAttribute("data-tab") === id;
      btn.className = "_eli3_tab" + (matches ? " _eli3_tab_active" : "");
    });
    unsubscribers.forEach(function (u) { try { u(); } catch (e) {} });
    unsubscribers = [];
    panel.innerHTML = "";
    var tab = TABS.find(function (t) { return t.id === id; });
    if (tab) tab.build(panel, unsubscribers);
  }

  showEliDialog({
    variant: "neutral",
    icon: "⚡",
    title: "ELI AI",
    body: '<div id="_eli3_tabbed_body" class="_eli3_tabbed_body_v2"></div>',
    buttons: [{
      label: "Close",
      cls: "btn-secondary",
      onclick: function (e, ov) {
        unsubscribers.forEach(function (u) { try { u(); } catch (err) {} });
        unsubscribers = [];
        if (ov.parentNode) ov.parentNode.removeChild(ov);
      },
    }],
    onMount: function (overlay) {
      var panelEl = overlay.querySelector(".eli-dialog");
      if (panelEl) panelEl.className += " _eli3_dialog_wide _eli3_dialog_tabbed_v2";
      var body = overlay.querySelector("#_eli3_tabbed_body");
      if (!body) return;
      var tabBar = document.createElement("div");
      tabBar.className = "_eli3_tabs";
      var contentEl;
      TABS.forEach(function (t) {
        var btn = document.createElement("div");
        btn.className = "_eli3_tab" + (t.id === activeId ? " _eli3_tab_active" : "");
        btn.setAttribute("data-tab", t.id);
        btn.textContent = t.label;
        btn.onclick = function () { _activate(t.id, contentEl, overlay); };
        tabBar.appendChild(btn);
      });
      body.appendChild(tabBar);
      contentEl = document.createElement("div");
      contentEl.className = "_eli3_tabpanel _eli3_tabpanel_fixed";
      contentEl.id = "_eli3_tabpanel";
      body.appendChild(contentEl);
      _activate(activeId, contentEl, overlay);
    },
  });

  // ── Help tab — Ask ELI AI + submit feedback + announcements ──────
  function _buildHelpTab(panel /*, unsubs */) {
    panel.appendChild(_buildAskAICard());
    panel.appendChild(_buildSubmitFeedbackCard());
    panel.appendChild(_buildAnnouncementsCard());
  }

  // ── Ask AI card — fed a system context that names every loaded tool ──
  function _buildAskAICard() {
    var sec = document.createElement("div");
    sec.className = "_eli3_help_card";
    sec.innerHTML =
      '<div class="_eli3_help_card_head">' +
        '<span class="_eli3_help_card_icon">✨</span>' +
        '<div class="_eli3_help_card_titles">' +
          '<div class="_eli3_help_card_title">Ask ELI AI</div>' +
          '<div class="_eli3_help_card_sub">Ask anything about ELI — what a tool does, how to do something, what the kernel handles.</div>' +
        '</div>' +
      '</div>' +
      '<textarea class="_eli3_help_ask_input" rows="2" placeholder="e.g. How does Build Draft decide which template to use?"></textarea>' +
      '<div class="_eli3_help_ask_row">' +
        '<button type="button" class="_eli3_help_btn_primary _eli3_help_ask_btn">Ask</button>' +
        '<span class="_eli3_help_ask_hint">Ctrl/Cmd + Enter to submit</span>' +
      '</div>' +
      '<div class="_eli3_help_ask_answer" style="display:none"></div>';
    var ta = sec.querySelector("._eli3_help_ask_input");
    var btn = sec.querySelector("._eli3_help_ask_btn");
    var ans = sec.querySelector("._eli3_help_ask_answer");
    function submit() {
      var q = (ta.value || "").trim();
      if (!q) { if (typeof showToast === "function") showToast("Type a question first.", "warn"); return; }
      if (!window.eli.ai || !window.eli.ai.complete) {
        ans.style.display = "block";
        ans.innerHTML = '<div class="_eli3_help_ask_err">⚠ AI not available — set an API key in Settings.</div>';
        return;
      }
      btn.disabled = true;
      var origLabel = btn.textContent;
      btn.textContent = "Thinking…";
      ans.style.display = "block";
      ans.innerHTML = '<div class="_eli3_help_ask_pending">⏳ Asking ELI AI…</div>';
      var prompt = _buildEliSystemContext() + "\n\nUSER QUESTION:\n" + q + "\n\nAnswer concisely in plain language. Point at specific tools by name when relevant. If you don't know, say so — don't invent tool names or capabilities.";
      window.eli.ai.complete(prompt, { maxTokens: 800 }).then(function (text) {
        ans.innerHTML = '<div class="_eli3_help_ask_answer_text">' + _formatAnswerHtml(text || "(no reply)") + '</div>';
        btn.disabled = false;
        btn.textContent = origLabel;
      }).catch(function (err) {
        ans.innerHTML = '<div class="_eli3_help_ask_err">⚠ ' + _esc((err && err.message) || "AI request failed") + '</div>';
        btn.disabled = false;
        btn.textContent = origLabel;
      });
    }
    btn.onclick = submit;
    ta.onkeydown = function (e) {
      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); submit(); }
    };
    return sec;
  }

  function _buildEliSystemContext() {
    var tools = [];
    try {
      var loaded = (window.eli && window.eli.tools && window.eli.tools._loaded) || {};
      Object.keys(loaded).sort().forEach(function (id) {
        var bundle = loaded[id];
        var cat = bundle && bundle.catalog;
        var title = (cat && cat.title) || id;
        var desc = (cat && cat.desc) || (cat && cat.description) || "";
        var icon = (cat && cat.icon) ? cat.icon + " " : "";
        tools.push("- " + icon + title + (desc ? ": " + desc : ""));
      });
    } catch (e) {}
    var toolListStr = tools.length ? tools.join("\n") : "(no tools currently loaded)";
    return "You are an assistant for ELI (Enhanced Legal Intelligence), an Office.js Word taskpane add-in for legal contract review. ELI is built around a small kernel (bootstrap, providers, UI primitives, storage) plus ~30 specialized tools that handle features (legal risk scanning, building drafts from templates, comparing versions, redline review, etc).\n\nTools currently installed:\n" + toolListStr;
  }

  // Render the AI answer as minimal HTML. Escape first, then apply a
  // small markdown subset (bold/italic/inline code) so models that
  // emit `**Foo**` show up styled instead of literal asterisks.
  function _formatAnswerHtml(text) {
    var safe = _esc(text);
    // Inline code — protect contents from bold/italic by handling first.
    safe = safe.replace(/`([^`\n]+)`/g, function (_m, c) { return "<code>" + c + "</code>"; });
    // **bold** and __bold__
    safe = safe.replace(/\*\*([^*\n]+?)\*\*/g, "<strong>$1</strong>");
    safe = safe.replace(/__([^_\n]+?)__/g, "<strong>$1</strong>");
    // *italic* — only when surrounded by word boundaries so list bullets
    // (lines starting with "* ") don't get eaten.
    safe = safe.replace(/(^|\W)\*([^*\n]+?)\*(?=\W|$)/g, "$1<em>$2</em>");
    return safe.split(/\n\n+/).map(function (para) {
      return "<p>" + para.replace(/\n/g, "<br>") + "</p>";
    }).join("");
  }

  // ── Submit feedback card — bug / improvement → GitHub or clipboard ──
  function _buildSubmitFeedbackCard() {
    var sec = document.createElement("div");
    sec.className = "_eli3_help_card";
    sec.innerHTML =
      '<div class="_eli3_help_card_head">' +
        '<span class="_eli3_help_card_icon">📣</span>' +
        '<div class="_eli3_help_card_titles">' +
          '<div class="_eli3_help_card_title">Report a bug or suggest an improvement</div>' +
          '<div class="_eli3_help_card_sub">Sent to the developer. Auto-includes the last 50 sanitized event log entries — no document content, no keys, no AI prompts.</div>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_help_typerow">' +
        '<label class="_eli3_help_typetile _eli3_help_typetile_active"><input type="radio" name="_eli3_fb_type" value="bug" checked><span>🐞 Bug</span></label>' +
        '<label class="_eli3_help_typetile"><input type="radio" name="_eli3_fb_type" value="improvement"><span>💡 Improvement</span></label>' +
      '</div>' +
      '<input type="text" class="_eli3_help_fb_title" placeholder="Title (one line)">' +
      '<textarea class="_eli3_help_fb_body" rows="3" placeholder="Describe what happened (for a bug) or what you\'d like (for an improvement)…"></textarea>' +
      '<div class="_eli3_help_fb_actions">' +
        '<button type="button" class="_eli3_help_btn_primary _eli3_help_fb_submit">Submit</button>' +
        '<button type="button" class="_eli3_help_btn_ghost _eli3_help_fb_copy">Copy report</button>' +
      '</div>' +
      '<div class="_eli3_help_fb_status"></div>';
    var typeRadios = sec.querySelectorAll('input[name="_eli3_fb_type"]');
    Array.prototype.slice.call(typeRadios).forEach(function (r) {
      r.onchange = function () {
        Array.prototype.slice.call(sec.querySelectorAll("._eli3_help_typetile")).forEach(function (lab) {
          var inp = lab.querySelector("input");
          if (inp && inp.checked) lab.classList.add("_eli3_help_typetile_active");
          else lab.classList.remove("_eli3_help_typetile_active");
        });
      };
    });
    var titleInp = sec.querySelector("._eli3_help_fb_title");
    var bodyInp  = sec.querySelector("._eli3_help_fb_body");
    var submitBtn = sec.querySelector("._eli3_help_fb_submit");
    var copyBtn   = sec.querySelector("._eli3_help_fb_copy");
    var statusEl  = sec.querySelector("._eli3_help_fb_status");
    function readForm() {
      var t = sec.querySelector('input[name="_eli3_fb_type"]:checked');
      return _buildFeedbackPayload({
        type: t ? t.value : "bug",
        title: (titleInp.value || "").trim(),
        description: (bodyInp.value || "").trim(),
      });
    }
    submitBtn.onclick = function () {
      var p = readForm();
      if (!p.title) { statusEl.innerHTML = '<span class="_eli3_help_fb_status_err">Title is required.</span>'; return; }
      submitBtn.disabled = true;
      statusEl.innerHTML = '<span class="_eli3_help_fb_status_pending">⏳ Submitting…</span>';
      _submitFeedback(p).then(function (res) {
        submitBtn.disabled = false;
        if (res && res.method === "github") {
          statusEl.innerHTML = '<span class="_eli3_help_fb_status_ok">✓ Submitted. Thanks!</span>';
          titleInp.value = ""; bodyInp.value = "";
        } else {
          statusEl.innerHTML = '<span class="_eli3_help_fb_status_warn">No upload credentials — report JSON copied to your clipboard. Email it to the developer.</span>';
        }
      }).catch(function (err) {
        submitBtn.disabled = false;
        statusEl.innerHTML = '<span class="_eli3_help_fb_status_err">' + _esc((err && err.message) || "Submit failed") + '</span>';
      });
    };
    copyBtn.onclick = function () {
      var p = readForm();
      if (!p.title) { statusEl.innerHTML = '<span class="_eli3_help_fb_status_err">Title is required.</span>'; return; }
      var json = JSON.stringify(p, null, 2);
      if (window.eli.ui && window.eli.ui.copyText) {
        window.eli.ui.copyText(json, "Feedback report");
      } else if (window._eliClipboardWriteOrFallback) {
        window._eliClipboardWriteOrFallback(json, "Feedback report");
      }
      statusEl.innerHTML = '<span class="_eli3_help_fb_status_ok">✓ Copied report JSON.</span>';
    };
    return sec;
  }

  function _buildFeedbackPayload(form) {
    var ident = (window.eli.tools && window.eli.tools.userIdentity) ? window.eli.tools.userIdentity() : {};
    var loaded = (window.eli.tools && window.eli.tools._loaded) || {};
    var events = [];
    try {
      events = (window.eli.log && window.eli.log.list ? window.eli.log.list() : []).slice(-50);
    } catch (e) {}
    var diag = (window.eli.diag && window.eli.diag.selfTest) ? window.eli.diag.selfTest() : { passed: 0, total: 0, ok: false };
    return {
      schemaVersion: 1,
      submittedAt: new Date().toISOString(),
      type: form.type,
      title: form.title,
      description: form.description,
      context: {
        kernelVersion: window.eli.kernelVersion || "(unknown)",
        online: !!(window.eli.network && window.eli.network.isOnline && window.eli.network.isOnline()),
        selfTest: diag.passed + "/" + diag.total + (diag.ok ? " ok" : " FAIL"),
        user: {
          email:     ident.email     || null,
          firstName: ident.firstName || null,
          name:      ident.name      || null,
          group:     ident.group     || null,
        },
        tools:  Object.keys(loaded),
        events: events,
      },
    };
  }

  function _submitFeedback(payload) {
    function _lsGet(k) {
      try { return (window.eli && window.eli.compat && window.eli.compat.lsGet) ? (window.eli.compat.lsGet(k) || "") : ""; }
      catch (e) { return ""; }
    }
    var pat    = _lsGet("eli_user_github_pat");
    var repo   = _lsGet("eli_github_repo");
    var branch = _lsGet("eli_github_branch") || "main";
    var json   = JSON.stringify(payload, null, 2);
    if (!pat || !repo) {
      // No PAT — clipboard fallback. Caller routes the user to email/paste.
      if (window.eli.ui && window.eli.ui.copyText) {
        return window.eli.ui.copyText(json, "Feedback report").then(function () { return { method: "copy" }; });
      }
      if (window._eliClipboardWriteOrFallback) {
        window._eliClipboardWriteOrFallback(json, "Feedback report");
      }
      return Promise.resolve({ method: "copy" });
    }
    var fname = "feedback/submissions/" + Date.now() + "_" + Math.random().toString(36).slice(2, 8) + ".json";
    var bytes = new TextEncoder().encode(json);
    var bin = "";
    for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
    var content = btoa(bin);
    return fetch("https://api.github.com/repos/" + repo + "/contents/" + fname, {
      method: "PUT",
      headers: {
        "Authorization": "Bearer " + pat,
        "Accept": "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        message: "feedback: " + payload.type + " — " + payload.title.slice(0, 60),
        content: content,
        branch: branch,
      }),
    }).then(function (r) {
      if (!r.ok) return r.text().then(function (t) { throw new Error("HTTP " + r.status + " · " + t.slice(0, 120)); });
      return { method: "github" };
    });
  }

  // ── Announcements card — fetch admin-curated list from CDN ───────
  function _buildAnnouncementsCard() {
    var sec = document.createElement("div");
    sec.className = "_eli3_help_card _eli3_help_card_announce";
    sec.innerHTML =
      '<div class="_eli3_help_card_head">' +
        '<span class="_eli3_help_card_icon">📢</span>' +
        '<div class="_eli3_help_card_titles">' +
          '<div class="_eli3_help_card_title">Known bugs &amp; shipped improvements</div>' +
          '<div class="_eli3_help_card_sub">Updates from the developer. NEW items appear with a badge until you click them.</div>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_help_announce_list">⏳ Loading…</div>';
    var list = sec.querySelector("._eli3_help_announce_list");
    _fetchAnnouncements().then(function (items) {
      _renderAnnouncements(list, items);
    }).catch(function (err) {
      // 2026-05-13 audit S4 fix: distinguish "no announcements file yet"
      // (HTTP 404 — expected on a fresh setup) from real failures
      // (network down, JSON parse error). Previously every failure
      // showed the same friendly message — masking real outages.
      var msg = (err && err.message) || "";
      if (/HTTP 404/.test(msg)) {
        list.innerHTML = '<div class="_eli3_help_announce_empty">No announcements yet.</div>';
      } else if (/Failed to fetch|NetworkError/i.test(msg) || !(window.eli.network && window.eli.network.isOnline && window.eli.network.isOnline())) {
        list.innerHTML = '<div class="_eli3_help_announce_empty">⚠ Couldn\'t reach the CDN — check your network and try again.</div>';
      } else {
        list.innerHTML = '<div class="_eli3_help_announce_empty">⚠ Failed to load: ' + (msg ? msg.replace(/[<>&]/g, "") : "unknown error") + '</div>';
      }
    });
    return sec;
  }

  function _fetchAnnouncements() {
    var url = "https://cdn.jsdelivr.net/gh/apndrewn/eli-data@main/feedback/announcements.json?t=" + Date.now();
    return fetch(url, { cache: "no-store" }).then(function (r) {
      if (!r.ok) throw new Error("HTTP " + r.status);
      return r.json();
    }).then(function (j) {
      return (j && Array.isArray(j.items)) ? j.items : [];
    });
  }

  function _renderAnnouncements(host, items) {
    var seen = {};
    function _paint() {
      if (!items || !items.length) {
        host.innerHTML = '<div class="_eli3_help_announce_empty">No announcements yet.</div>';
        return;
      }
      host.innerHTML = items.map(function (it) {
        var isNew = !seen[it.id];
        var icon = it.type === "improvement" ? "💡" : "🐞";
        var statusCls = "_eli3_status_" + ((it.status || "open").replace(/[^a-z0-9_-]/gi, "") || "open");
        var statusTxt = it.status || "open";
        return '<div class="_eli3_help_announce_row' + (isNew ? " _eli3_help_announce_new" : "") + '" data-fb-id="' + _esc(it.id) + '">' +
          '<span class="_eli3_help_announce_icon">' + icon + '</span>' +
          '<div class="_eli3_help_announce_meta">' +
            '<div class="_eli3_help_announce_title">' + _esc(it.title || "(untitled)") + (isNew ? ' <span class="_eli3_help_announce_newbadge">NEW</span>' : '') + '</div>' +
            (it.summary ? '<div class="_eli3_help_announce_sum">' + _esc(it.summary) + '</div>' : '') +
            '<div class="_eli3_help_announce_footer">' +
              '<span class="_eli3_help_announce_status ' + statusCls + '">' + _esc(statusTxt) + '</span>' +
              (it.postedAt ? '<span class="_eli3_help_announce_time">' + _esc(_relTime(it.postedAt)) + '</span>' : '') +
            '</div>' +
          '</div>' +
        '</div>';
      }).join("");
      Array.prototype.slice.call(host.querySelectorAll("[data-fb-id]")).forEach(function (row) {
        row.onclick = function () {
          var id = row.getAttribute("data-fb-id");
          if (!id) return;
          seen[id] = true;
          if (window.eli.storage && window.eli.storage.put) {
            window.eli.storage.put("config", { key: "_feedback_seen", seen: seen });
          }
          row.classList.remove("_eli3_help_announce_new");
          var badge = row.querySelector("._eli3_help_announce_newbadge");
          if (badge && badge.parentNode) badge.parentNode.removeChild(badge);
        };
      });
    }
    if (window.eli.storage && window.eli.storage.get) {
      window.eli.storage.get("config", "_feedback_seen").then(function (r) {
        if (r && r.seen) seen = r.seen;
        _paint();
      }).catch(_paint);
    } else { _paint(); }
  }

  function _relTime(iso) {
    if (!iso) return "";
    var t = new Date(iso).getTime();
    if (isNaN(t)) return "";
    var diff = Date.now() - t;
    var min = 60000, hr = 3600000, day = 86400000;
    if (diff < hr) return Math.max(1, Math.floor(diff / min)) + "m ago";
    if (diff < day) return Math.floor(diff / hr) + "h ago";
    if (diff < 30 * day) return Math.floor(diff / day) + "d ago";
    return new Date(iso).toLocaleDateString();
  }

  // ── About tab — credit + system stats, no buttons ────────────────
  function _buildAboutTab(panel /*, unsubs */) {
    var ident = (window.eli.tools && window.eli.tools.userIdentity) ? window.eli.tools.userIdentity() : {};
    var diag = (window.eli.diag && window.eli.diag.selfTest) ? window.eli.diag.selfTest() : { passed: 0, total: 0, ok: false };
    var caps = (window.eli.host && window.eli.host.capabilities) ? window.eli.host.capabilities() : {};
    var online = (window.eli.network && window.eli.network.isOnline) ? window.eli.network.isOnline() : true;
    var bootMs = (window.eli.perf && window.eli.perf.measure) ? window.eli.perf.measure("boot:office_ready", "boot:first_paint") : null;
    var toolCount = (window.eli.tools && window.eli.tools._loaded) ? Object.keys(window.eli.tools._loaded).length : 0;

    var wrap = document.createElement("div");
    wrap.className = "_eli3_about_root";
    wrap.innerHTML =
      '<div class="_eli3_about_hero">' +
        '<div class="_eli3_about_logo">⚡</div>' +
        '<div class="_eli3_about_brand">' +
          '<div class="_eli3_about_brand_name">ELI</div>' +
          '<div class="_eli3_about_brand_tag">Enhanced Legal Intelligence</div>' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_about_lead">An AI-assisted contract review add-in for Microsoft Word. A small kernel hosts ~30 specialized tools — legal risk scanning, draft building, version comparison, redline review, and more.</div>' +
      '<div class="_eli3_about_credit">' +
        '<div class="_eli3_about_credit_eyebrow">DEVELOPED BY</div>' +
        '<div class="_eli3_about_credit_name">Andrew Nemiroff</div>' +
      '</div>' +
      '<div class="_eli3_about_stats">' +
        _aboutStat("Kernel",    window.eli.kernelVersion || "—") +
        _aboutStat("Boot",      bootMs == null ? "—" : bootMs + "ms") +
        _aboutStat("Tools",     String(toolCount)) +
        _aboutStat("Self-test", diag.passed + "/" + diag.total + (diag.ok ? " ✓" : " ✗")) +
        _aboutStat("Online",    online ? "Yes" : "No") +
        _aboutStat("Word host", caps.hasWord ? "Yes" : "No") +
      '</div>' +
      '<div class="_eli3_about_userblock">' +
        '<div class="_eli3_about_credit_eyebrow">SIGNED IN AS</div>' +
        '<div class="_eli3_about_user_line">' + _esc(ident.name || ident.firstName || "(no name set)") + '</div>' +
        (ident.email
          ? '<div class="_eli3_about_user_sub">' + _esc(ident.email) + (ident.group ? " · " + _esc(ident.group) : "") + '</div>'
          : '') +
      '</div>';
    panel.appendChild(wrap);
  }
  function _aboutStat(label, value) {
    return '<div class="_eli3_about_stat">' +
      '<div class="_eli3_about_stat_label">' + _esc(label) + '</div>' +
      '<div class="_eli3_about_stat_value">' + _esc(value) + '</div>' +
    '</div>';
  }

  // ── Debug Console tab ──
  function _buildConsoleTab(panel, unsubs) {
    var toolbar = document.createElement("div");
    toolbar.className = "_eli3_console_toolbar";

    var allBtn = _filterBtn("All", null, true);
    toolbar.appendChild(allBtn);

    var filterChannel = null;
    var filterBtns = [allBtn];

    function _setFilter(channel, btn) {
      filterChannel = channel;
      filterBtns.forEach(function (b) {
        b.className = "_eli3_filter_btn" + (b === btn ? " _eli3_filter_btn_active" : "");
      });
      _renderRows();
    }
    allBtn.onclick = function () { _setFilter(null, allBtn); };

    var channels = _uniqueChannels();
    channels.forEach(function (ch) {
      var b = _filterBtn(ch, ch, false);
      b.onclick = function () { _setFilter(ch, b); };
      filterBtns.push(b);
      toolbar.appendChild(b);
    });

    var spacer = document.createElement("span");
    spacer.style.flex = "1";
    toolbar.appendChild(spacer);

    var meta = document.createElement("span");
    meta.className = "_eli3_console_meta";
    toolbar.appendChild(meta);

    toolbar.appendChild(eliButton({
      label: "📋 Copy",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () { window.eli.log.copyToClipboard(); },
    }));
    toolbar.appendChild(eliButton({
      label: "Clear",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () {
        window.eli.log.clear();
        _renderRows();
      },
    }));
    panel.appendChild(toolbar);

    var list = document.createElement("div");
    list.className = "_eli3_log_list";
    panel.appendChild(list);

    function _renderRows() {
      list.innerHTML = "";
      var events = window.eli.log.list();
      if (filterChannel) events = events.filter(function (e) { return e.channel === filterChannel; });
      meta.textContent = events.length + " / " + window.eli.log.MAX_EVENTS + " events";
      if (!events.length) {
        var empty = document.createElement("div");
        empty.className = "_eli3_log_empty";
        empty.textContent = filterChannel ? "No events on '" + filterChannel + "'" : "No events.";
        list.appendChild(empty);
        return;
      }
      events.slice().reverse().forEach(function (ev) { list.appendChild(_renderRow(ev)); });
    }

    function _renderRow(ev) {
      var row = document.createElement("div");
      row.className = "_eli3_log_row";
      var t = document.createElement("span");
      t.className = "_eli3_log_time";
      t.textContent = _formatTime(ev.timestamp);
      row.appendChild(t);
      var c = document.createElement("span");
      c.className = "_eli3_log_chan";
      c.textContent = ev.channel;
      row.appendChild(c);
      var m = document.createElement("span");
      m.className = "_eli3_log_msg";
      m.textContent = ev.name;
      row.appendChild(m);
      if (ev.payload != null) {
        var p = document.createElement("div");
        p.className = "_eli3_log_payload";
        try { p.textContent = JSON.stringify(ev.payload); }
        catch (e) { p.textContent = String(ev.payload); }
        row.appendChild(p);
      }
      return row;
    }

    function _formatTime(ts) {
      var d = new Date(ts);
      var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
      return pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
    }
    function _uniqueChannels() {
      var out = {};
      window.eli.log.list().forEach(function (e) { out[e.channel] = true; });
      return Object.keys(out).sort();
    }

    _renderRows();
    var unsub = window.eli.log.subscribe(function (entry) {
      var existing = filterBtns.map(function (b) { return b.getAttribute("data-ch"); });
      if (entry.channel && existing.indexOf(entry.channel) === -1) {
        var b = _filterBtn(entry.channel, entry.channel, false);
        b.onclick = function () { _setFilter(entry.channel, b); };
        filterBtns.push(b);
        toolbar.insertBefore(b, spacer);
      }
      _renderRows();
    });
    unsubs.push(unsub);
  }

  function _filterBtn(label, channel, active) {
    var b = document.createElement("span");
    b.className = "_eli3_filter_btn" + (active ? " _eli3_filter_btn_active" : "");
    b.textContent = label;
    if (channel) b.setAttribute("data-ch", channel);
    return b;
  }
}


// ─── Wrongness debug viewer (NEW UI) ─────────────────────────────────
// No v2 source — built fresh on top of eli.wrongness.list/getCapture/
// replayCapture/clear/copyToClipboard.
//
// Surface:
//   - Toolbar: tool-id filter dropdown · Copy All · Clear All · count meter
//   - Scrollable list: each row shows {timestamp, toolId, kind (capture|flag), id-hash}
//   - Click a row → expanded detail with provenance + sanitized input/output JSON,
//     plus per-row Replay + Copy buttons.
//
// opts (all optional): {} — viewer reads from window.eli.wrongness.* directly.

view.renderWrongness:
function renderWrongness(/* opts */) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Wrongness viewer requires showEliDialog", "err");
    return;
  }
  if (!window.eli.wrongness || typeof window.eli.wrongness.list !== "function") {
    if (typeof showToast === "function") showToast("eli.wrongness API unavailable", "err");
    return;
  }

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  function _formatTime(ts) {
    if (!ts) return "—";
    var d = new Date(ts);
    var pad = function (n) { return n < 10 ? "0" + n : "" + n; };
    return d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
           " " + pad(d.getHours()) + ":" + pad(d.getMinutes()) + ":" + pad(d.getSeconds());
  }
  function _shortId(id) {
    var s = String(id || "");
    var i = s.lastIndexOf("_");
    return i > -1 ? s.slice(i + 1) : s.slice(-6);
  }

  var _filterTool = ""; // "" = all
  var _expandedId = null;
  var _entries = [];
  var _overlayRef = null;

  function _refresh() {
    return window.eli.wrongness.list().then(function (rows) {
      _entries = rows || [];
      if (_overlayRef) _renderBody(_overlayRef);
    }).catch(function (err) {
      if (typeof showToast === "function") showToast("Load failed: " + (err && err.message || "unknown"), "err");
    });
  }

  function _filteredEntries() {
    if (!_filterTool) return _entries;
    return _entries.filter(function (e) { return (e.toolId || "") === _filterTool; });
  }

  function _uniqueToolIds() {
    var s = {};
    _entries.forEach(function (e) { if (e.toolId) s[e.toolId] = true; });
    return Object.keys(s).sort();
  }

  function _renderToolbar(host) {
    host.innerHTML = "";
    var bar = document.createElement("div");
    bar.className = "_eli3_wrong_toolbar";
    bar.style.cssText = "display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding-bottom:8px;border-bottom:1px solid #ececec;margin-bottom:8px";

    var label = document.createElement("span");
    label.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;text-transform:uppercase;letter-spacing:.04em";
    label.textContent = "Tool:";
    bar.appendChild(label);

    var sel = document.createElement("select");
    sel.style.cssText = "font:11px system-ui;padding:2px 6px;border:1px solid #d6dbe1;border-radius:4px";
    var optAll = document.createElement("option");
    optAll.value = "";
    optAll.textContent = "All";
    sel.appendChild(optAll);
    _uniqueToolIds().forEach(function (id) {
      var o = document.createElement("option");
      o.value = id;
      o.textContent = id;
      sel.appendChild(o);
    });
    sel.value = _filterTool;
    sel.onchange = function () { _filterTool = sel.value; _renderBody(_overlayRef); };
    bar.appendChild(sel);

    var spacer = document.createElement("span");
    spacer.style.flex = "1";
    bar.appendChild(spacer);

    var meter = document.createElement("span");
    var filtered = _filteredEntries();
    meter.style.cssText = "font:11px system-ui;color:#5a6368";
    meter.textContent = filtered.length + " / " + _entries.length + " entries (max " + (window.eli.wrongness.MAX_CAPTURES || 50) + ")";
    bar.appendChild(meter);

    bar.appendChild(eliButton({
      label: "📋 Copy Corpus",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () { window.eli.wrongness.copyToClipboard(); },
    }));
    bar.appendChild(eliButton({
      label: "Clear All",
      variant: "secondary",
      style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
      onclick: function () {
        if (!_entries.length) return;
        if (window.eli.ui && typeof window.eli.ui.confirm === "function") {
          window.eli.ui.confirm({
            title: "Clear all wrongness captures?",
            message: "This deletes all " + _entries.length + " captures and flags from IDB. Cannot be undone.",
            confirmLabel: "Clear All",
            destructive: true,
          }).then(function (ok) {
            if (!ok) return;
            window.eli.wrongness.clear().then(_refresh);
          });
        } else {
          window.eli.wrongness.clear().then(_refresh);
        }
      },
    }));

    host.appendChild(bar);
  }

  function _renderList(host) {
    var filtered = _filteredEntries();
    if (!filtered.length) {
      var empty = document.createElement("div");
      empty.style.cssText = "padding:30px 16px;text-align:center;color:#7f8c8d;font:12px system-ui";
      empty.textContent = _filterTool
        ? "No entries for tool '" + _filterTool + "'."
        : "No wrongness captures yet. Tools call eli.wrongness.capture() after each engine run.";
      host.appendChild(empty);
      return;
    }
    var listEl = document.createElement("div");
    listEl.className = "_eli3_wrong_list";
    listEl.style.cssText = "display:flex;flex-direction:column;gap:4px;max-height:420px;overflow-y:auto";

    filtered.forEach(function (entry) {
      var ts = entry.capturedAt || entry.flaggedAt;
      var isFlag = entry.kind === "flag";
      var row = document.createElement("div");
      row.className = "_eli3_wrong_row";
      row.style.cssText = "border:1px solid #ececec;border-radius:6px;background:#fafbfc;font:11px/1.4 system-ui";

      var head = document.createElement("div");
      head.style.cssText = "display:flex;gap:10px;align-items:center;padding:6px 10px;cursor:pointer";
      head.onclick = function () {
        _expandedId = (_expandedId === entry.id) ? null : entry.id;
        _renderBody(_overlayRef);
      };

      var kindBadge = document.createElement("span");
      kindBadge.style.cssText = "font:600 9px/1 system-ui;letter-spacing:.04em;padding:2px 5px;border-radius:3px;text-transform:uppercase;color:#fff;background:" + (isFlag ? "#c0392b" : "#3498db");
      kindBadge.textContent = isFlag ? "Flag" : "Capture";
      head.appendChild(kindBadge);

      var tid = document.createElement("span");
      tid.style.cssText = "font:600 11px system-ui;color:#2c3e50";
      tid.textContent = entry.toolId || "(no toolId)";
      head.appendChild(tid);

      var time = document.createElement("span");
      time.style.cssText = "color:#7f8c8d;font:11px system-ui";
      time.textContent = _formatTime(ts);
      head.appendChild(time);

      var spacer = document.createElement("span");
      spacer.style.flex = "1";
      head.appendChild(spacer);

      var idTag = document.createElement("span");
      idTag.style.cssText = "color:#95a5a6;font:10px monospace";
      idTag.textContent = "#" + _shortId(entry.id);
      head.appendChild(idTag);

      var caret = document.createElement("span");
      caret.style.cssText = "color:#7f8c8d;font:10px monospace;width:10px;text-align:right";
      caret.textContent = (_expandedId === entry.id) ? "▾" : "▸";
      head.appendChild(caret);

      row.appendChild(head);

      if (_expandedId === entry.id) {
        var detail = document.createElement("div");
        detail.style.cssText = "padding:8px 10px;border-top:1px solid #ececec;background:#fff";

        if (isFlag) {
          if (entry.findingId) {
            detail.appendChild(_kvLine("Finding ID", entry.findingId));
          }
          if (entry.note) {
            detail.appendChild(_kvLine("Note", entry.note));
          }
        }
        if (entry.provenance) {
          var provBlock = document.createElement("div");
          provBlock.style.cssText = "margin-top:6px";
          var pTitle = document.createElement("div");
          pTitle.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em";
          pTitle.textContent = "Provenance";
          provBlock.appendChild(pTitle);
          var pre = document.createElement("pre");
          pre.style.cssText = "margin:0;padding:6px 8px;background:#f4f6f8;border-radius:4px;font:10px/1.4 monospace;white-space:pre-wrap;word-break:break-all;max-height:120px;overflow-y:auto";
          try { pre.textContent = JSON.stringify(entry.provenance, null, 2); }
          catch (e) { pre.textContent = "(unstringifiable)"; }
          provBlock.appendChild(pre);
          detail.appendChild(provBlock);
        }
        if (!isFlag) {
          detail.appendChild(_jsonBlock("Input (sanitized)", entry.input));
          detail.appendChild(_jsonBlock("Output (sanitized)", entry.output));
        }

        var actions = document.createElement("div");
        actions.style.cssText = "display:flex;gap:6px;margin-top:8px;flex-wrap:wrap";
        if (!isFlag) {
          actions.appendChild(eliButton({
            label: "▶ Replay",
            variant: "secondary",
            style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
            onclick: function () {
              window.eli.wrongness.replayCapture(entry.id).then(function (res) {
                if (typeof showToast === "function") showToast("Replay finished in " + res.ms + "ms — see console", "ok");
                if (window.eli.log && window.eli.log.event) {
                  window.eli.log.event("wrongness", "replay_done", { captureId: entry.id, ms: res.ms });
                }
              }).catch(function (err) {
                if (typeof showToast === "function") showToast("Replay failed: " + (err && err.message || "unknown"), "err");
              });
            },
          }));
        }
        actions.appendChild(eliButton({
          label: "📋 Copy Entry",
          variant: "secondary",
          style: "padding:3px 9px;font:600 10px/1.2 system-ui;",
          onclick: function () {
            var json;
            try { json = JSON.stringify(entry, null, 2); }
            catch (e) { json = "(unstringifiable entry)"; }
            if (window.eli.ui && typeof window.eli.ui.copyText === "function") {
              window.eli.ui.copyText(json, "Wrongness entry " + _shortId(entry.id));
            } else if (typeof showToast === "function") {
              showToast("Copy unavailable (eli.ui.copyText missing)", "err");
            }
          },
        }));
        detail.appendChild(actions);
        row.appendChild(detail);
      }

      listEl.appendChild(row);
    });

    host.appendChild(listEl);
  }

  function _kvLine(label, value) {
    var row = document.createElement("div");
    row.style.cssText = "display:flex;gap:8px;font:11px system-ui;margin-top:4px";
    var l = document.createElement("span");
    l.style.cssText = "font:600 10px/1.4 system-ui;color:#5a6368;min-width:80px;text-transform:uppercase;letter-spacing:.04em";
    l.textContent = label;
    var v = document.createElement("span");
    v.style.cssText = "color:#2c3e50;word-break:break-all";
    v.textContent = String(value == null ? "" : value);
    row.appendChild(l);
    row.appendChild(v);
    return row;
  }

  function _jsonBlock(title, value) {
    var block = document.createElement("div");
    block.style.cssText = "margin-top:6px";
    var t = document.createElement("div");
    t.style.cssText = "font:600 10px/1 system-ui;color:#5a6368;margin-bottom:4px;text-transform:uppercase;letter-spacing:.04em";
    t.textContent = title;
    block.appendChild(t);
    var pre = document.createElement("pre");
    pre.style.cssText = "margin:0;padding:6px 8px;background:#f4f6f8;border-radius:4px;font:10px/1.4 monospace;white-space:pre-wrap;word-break:break-all;max-height:200px;overflow-y:auto";
    try { pre.textContent = (value == null) ? "(none)" : JSON.stringify(value, null, 2); }
    catch (e) { pre.textContent = "(unstringifiable)"; }
    block.appendChild(pre);
    return block;
  }

  function _renderBody(overlay) {
    if (!overlay) return;
    var desc = overlay.querySelector(".eli-dialog-desc");
    if (!desc) return;
    desc.innerHTML = '<div id="_eli3_wrong_root"></div>';
    var root = desc.querySelector("#_eli3_wrong_root");
    _renderToolbar(root);
    _renderList(root);
  }

  showEliDialog({
    variant: "neutral",
    icon: "🐞",
    title: "Wrongness Debug Viewer",
    body: '<div id="_eli3_wrong_root">Loading…</div>',
    secondary: { label: "Close" },
    onMount: function (overlay) {
      _overlayRef = overlay;
      var panelEl = overlay.querySelector(".eli-dialog");
      if (panelEl) panelEl.className += " _eli3_dialog_wide";
      _refresh();
    },
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["eli_kit"];
  if (!bundle) return;

  // ─── Install full clipboard helper (kernel had only direct-write stub) ──
  // 2026-05-12 offload from kernel §16.9. Replaces window._eliClipboardWriteOrFallback
  // with the focus-fallback dialog. Kernel stub stays as the boot-time
  // fallback so anything that calls before eli_kit loads gets at least
  // navigator.clipboard.writeText (no UI).
  window._eliClipboardWriteOrFallback = function (text, label) {
    if (typeof navigator !== "undefined" && navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function () {
        _eliKitShowCopyFallback(text, label);
      });
    }
    _eliKitShowCopyFallback(text, label);
    return Promise.resolve();
  };
  function _eliKitShowCopyFallback(text, label) {
    if (typeof showEliDialog !== "function") return;
    var safe = String(text || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
    var taId = "_eli3_copy_ta_" + Date.now();
    showEliDialog({
      variant: "info",
      icon: "📋",
      title: label || "Copy to clipboard",
      body:
        '<div class="_eli3_copy_hint">Auto-selected. Press <b>Ctrl+C</b> (or <b>⌘C</b> on Mac) to copy, then paste in chat.</div>' +
        '<textarea id="' + taId + '" readonly class="_eli3_copy_textarea">' + safe + '</textarea>',
      buttons: [{
        label: "Try direct copy",
        onclick: function (e, ov) {
          try {
            if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
              navigator.clipboard.writeText(text).then(function () {
                if (typeof showToast === "function") showToast("Copied to clipboard.", "ok");
                if (ov.parentNode) ov.parentNode.removeChild(ov);
              }).catch(function () {
                if (typeof showToast === "function") showToast("Direct copy still blocked. Use Ctrl+C from textarea.", "warn");
              });
            }
          } catch (e2) {}
        },
      }, {
        label: "Done",
        cls: "btn-secondary",
        onclick: function (e, ov) { if (ov.parentNode) ov.parentNode.removeChild(ov); },
      }],
      onMount: function (ov) {
        setTimeout(function () {
          var ta = ov.querySelector("#" + taId);
          if (ta) {
            try { ta.focus(); ta.select(); } catch (e) {}
          }
        }, 80);
      },
    });
  }
  var vfns = bundle._eliViewFns || {};
  var renderCustomize = vfns.renderCustomize;
  var renderTabbedDialog = vfns.renderTabbedDialog;
  var renderWrongness = vfns.renderWrongness;
  if (!renderCustomize || !renderTabbedDialog || !renderWrongness) {
    eli.log.event("tool", "eli_kit_load_failed", {
      hasCustomize: !!renderCustomize,
      hasTabbedDialog: !!renderTabbedDialog,
      hasWrongness: !!renderWrongness,
    });
    return;
  }

  // ── Customize Dashboard ─────────────────────────────────────────
  function openCustomize() {
    if (!eli.dashboard ||
        typeof eli.dashboard.getVisibleTools !== "function" ||
        typeof eli.dashboard.getPinState !== "function") {
      if (typeof showToast === "function") showToast("Dashboard reader API missing — kernel too old", "err");
      return;
    }
    renderCustomize({
      getVisibleTools: function () { return eli.dashboard.getVisibleTools(); },
      getPinState:     function () { return eli.dashboard.getPinState(); },
      pin:             function (catId) { return eli.dashboard.pin(catId); },
      unpin:           function (catId) { return eli.dashboard.unpin(catId); },
      movePin:         function (catId, dir) { return eli.dashboard.movePin(catId, dir); },
      resetPins:       function () { return eli.dashboard.resetPins(); },
    });
  }

  // ── Help / About / Debug Console ────────────────────────────────
  // Accepts a string ("help"|"about"|"console") OR a payload object
  // {initialTab}. Kernel header click historically dispatched "console";
  // the 2026-05-13 rewrite leads with the new Help (Ask AI + feedback)
  // tab, so we silently remap that legacy string. Power-users who want
  // the event-log viewer click the Debug tab themselves.
  function openHelp(arg) {
    var initialTab = (typeof arg === "string") ? arg :
                     (arg && arg.initialTab) || "help";
    if (initialTab === "console" && !(arg && arg.initialTab)) initialTab = "help";
    if (initialTab === "contact") initialTab = "about"; // legacy alias
    renderTabbedDialog({ initialTab: initialTab });
  }

  // ── Wrongness viewer ────────────────────────────────────────────
  function openWrongness() {
    renderWrongness({});
  }

  eli.register({
    kit: {
      customize: openCustomize,
      help:      openHelp,
      wrongness: openWrongness,
    },
  });

  eli.log.event("tool", "eli_kit_initialized", {});
}

jsonTools.css:
/* tools/eli_kit/style.css
 * Three surfaces moved here from taskpane_v3.css 2026-05-11 (Batch 5E):
 *   - Customize Dashboard modal body (was kernel 1161-1320)
 *   - ._eli3_dialog_wide  (was kernel 1965 — shared by tabbed dialog +
 *     wrongness viewer)
 *   - Tabbed dialog (Help / Contact / Console) + helpers (was 2476-2679)
 *
 * The wrongness viewer uses inline styles in view.js (no class CSS yet).
 * Bundle CSS is auto-injected by the kernel at eval time and removed on
 * uninstall, so deploys without eli_kit ship without these rules.
 */

/* ─── §7.2  Customize Dashboard modal body
 *   What: rendered inside showEliDialog's `.eli-dialog-desc` slot.
 *         Two stacked sections (Installed apps / Available apps) with
 *         row-style item cards + action buttons. Reset link at the
 *         bottom.
 */
._eli3_customize_intro {
  font: 500 11.5px/1.5 'Inter', sans-serif;
  color: #475569;
  margin: 0 0 10px;
}
/* Customize dialog: kill horizontal scrollbar (items + buttons stay
 * inside the dialog width) and keep all action buttons (↑↓✕, +)
 * visible at the row edge without overflow. */
._eli3_customize_dialog { overflow-x: hidden; }
._eli3_customize_dialog ._eli3_customize_item {
  min-width: 0; /* allow text to truncate instead of forcing horizontal scroll */
}
._eli3_customize_dialog ._eli3_customize_actions {
  flex-shrink: 0; /* + and ↑↓✕ buttons never get clipped */
}
._eli3_customize_dialog ._eli3_customize_meta {
  min-width: 0;
  overflow: hidden;
}

._eli3_customize_body {
  display: flex; flex-direction: column; gap: 14px;
  text-align: left;
}
._eli3_customize_section {
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_customize_subtitle {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_customize_list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  padding: 6px;
  /* Single scroll for the WHOLE customize panel — handled by the
     dialog body (.eli-dialog-desc). Don't add an inner overflow:auto
     here or the panel grows two nested scrollbars when both the list
     and the dialog body exceed their box. */
  overflow: visible;
}
._eli3_customize_list ._eli3_customize_catheader,
._eli3_customize_list ._eli3_customize_empty {
  width: 100%;
}
._eli3_customize_list_avail { background: transparent; border: 0; padding: 0; }
._eli3_customize_catheader {
  font: 700 9.5px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #64748b;
  padding: 8px 10px 4px;
  background: transparent;
}
._eli3_customize_item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  background: #fff;
  border: 1px solid #e2e8f0;
  margin: 2px 0;
}
._eli3_customize_item_pinned { background: #fff; }
._eli3_customize_item_avail {
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s;
}
._eli3_customize_item_avail:hover {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_customize_item_core {
  border-color: rgba(201, 162, 39, 0.55);
  background: rgba(254, 249, 219, 0.6);
}
._eli3_customize_icon {
  flex: 0 0 auto;
  width: 26px; height: 26px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 16px;
}
._eli3_customize_meta {
  flex: 1 1 auto;
  min-width: 0;
}
._eli3_customize_name {
  font: 700 12px/1.2 'Inter', sans-serif;
  color: #0f172a;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_customize_desc {
  font: 500 10.5px/1.3 'Inter', sans-serif;
  color: #64748b;
  margin-top: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
._eli3_customize_corebadge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 5px;
  font: 700 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  background: rgba(201, 162, 39, 0.18);
  color: #92400e;
  border: 1px solid rgba(201, 162, 39, 0.5);
  vertical-align: middle;
}
._eli3_customize_actions {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 4px;
}
._eli3_customize_btn {
  width: 24px; height: 24px;
  display: inline-flex; align-items: center; justify-content: center;
  font: 700 12px/1 'Inter', sans-serif;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #cbd5e1;
  cursor: pointer;
  transition: all 0.12s;
  user-select: none;
}
._eli3_customize_btn:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}
._eli3_customize_btn_remove:hover {
  background: #fef2f2 !important;
  color: #b91c1c !important;
  border-color: #fca5a5 !important;
}
._eli3_customize_btn_add {
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border-color: #0d47a1;
  font-size: 14px;
}
._eli3_customize_btn_add:hover {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%) !important;
  color: #fff !important;
  border-color: #0d47a1 !important;
}
._eli3_customize_locked {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 1px;
  color: rgba(180, 83, 9, 0.8);
  padding: 0 8px;
}
._eli3_customize_empty {
  padding: 12px;
  font: 500 11px/1.5 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
  text-align: center;
}
._eli3_customize_resetrow {
  display: flex; justify-content: flex-end;
  padding-top: 8px;
  border-top: 1px solid #e2e8f0;
}
._eli3_customize_reset {
  background: none; border: 0;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #94a3b8;
  cursor: pointer;
  padding: 4px 8px;
  transition: color 0.12s;
}
._eli3_customize_reset:hover { color: #b91c1c; text-decoration: underline; }

/* Dark mode — user-requested 2026-05-11. Customize lives in the dashboard
 * chrome (the + button anchors here), so it follows the same theme as the
 * unpinned menu rather than the dialog default. Palette mirrors v2's
 * openCatalogModal dark variant. Scoped to the dialog wrapper so it
 * doesn't leak into other dialogs that happen to embed customize-style
 * rows. */
body:not(.light-mode) ._eli3_customize_dialog {
  background: #0f172a;
  color: #f1f5f9;
}
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-desc { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-title { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog .eli-dialog-close { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_intro { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_subtitle {
  color: #f2d866;
  border-bottom-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_list {
  background: #1e293b;
  border-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_list_avail {
  background: transparent;
  border: 0;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_catheader { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item,
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_pinned {
  background: #1e293b;
  border-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_avail:hover {
  background: #334155;
  border-color: #475569;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_item_core {
  border-color: rgba(201,162,39,0.55);
  background: rgba(201,162,39,0.10);
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_name { color: #f1f5f9; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_desc { color: #94a3b8; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_corebadge {
  background: rgba(201,162,39,0.20);
  color: #f2d866;
  border-color: rgba(201,162,39,0.55);
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn {
  background: linear-gradient(to bottom, #334155 0%, #1e293b 100%);
  color: #cbd5e1;
  border-color: #475569;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn:hover:not(:disabled) {
  background: linear-gradient(to bottom, #475569 0%, #334155 100%);
  color: #f2d866;
  border-color: #64748b;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_btn_remove:hover {
  background: #7f1d1d !important;
  color: #fecaca !important;
  border-color: #b91c1c !important;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_locked { color: #f2d866; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_empty { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_resetrow {
  border-top-color: #334155;
}
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset { color: #64748b; }
body:not(.light-mode) ._eli3_customize_dialog ._eli3_customize_reset:hover { color: #fecaca; }

/* ── Shared dialog widening — used by both the tabbed dialog and the wrongness viewer ── */
._eli3_dialog_wide { width: 620px; max-width: 94vw; }

/* ─── §15  Tabbed dialog (ELI logo click → Help/Contact/Console)
 *   What: tab bar at top of the dialog body + active-tab underline +
 *     individual tab panels (help, contact, console).
 *   Who emits: kernel's _tabbedDialog() + _buildHelpTab / _buildContactTab
 *     / _buildConsoleTab.
 *   Override: rare. Tool authors don't customize this dialog. */
._eli3_tabs {
  display: flex;
  gap: 0;
  border-bottom: 2px solid #e2e8f0;
  margin-bottom: var(--space-3);
}
._eli3_tab {
  padding: var(--space-2) 14px;
  font: var(--weight-bold) var(--font-md)/1.2 var(--font-family);
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: var(--text-status-footer);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  transition: color .15s, border-color .15s;
}
._eli3_tab:hover { color: var(--color-blue); }
._eli3_tab_active {
  color: var(--color-blue);
  border-bottom-color: var(--color-blue);
}
._eli3_tabpanel {
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-on-light);
  /* Lock height so dialog doesn't reflow when switching tabs.
     Sized to fit the tallest tab (Console: toolbar + 360px log list). */
  min-height: 420px;
}
/* 2026-05-13 rewrite — pin tab body so all three tabs match height
   exactly + scroll internally when content overflows. */
._eli3_tabpanel_fixed {
  height: 460px;
  overflow-y: auto;
  padding-right: 4px; /* breathing room for the inner scrollbar */
}

/* Help tab */
._eli3_help_section {
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-3);
  border-bottom: 1px solid #f1f5f9;
}
._eli3_help_section:last-child { border-bottom: none; padding-bottom: 0; }
._eli3_help_section h4 {
  font: var(--weight-extrabold) var(--font-md)/1.3 var(--font-family);
  letter-spacing: 0.6px;
  text-transform: uppercase;
  color: var(--color-blue);
  margin: 0 0 var(--space-2);
}
._eli3_help_section p {
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
  margin: 0 0 var(--space-2);
}
._eli3_help_section ul {
  margin: var(--space-1) 0 0 var(--space-3);
  padding: 0;
}
._eli3_help_section li {
  margin-bottom: var(--space-1);
  font-size: 12px;
  line-height: 1.55;
  color: var(--text-on-light);
}
._eli3_help_section code {
  font-family: var(--font-mono);
  font-size: var(--font-md);
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 1px var(--space-1);
  color: var(--text-on-light);
}

/* Help → Recovery actions block */
#_eli3_help_recovery_btns {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: var(--space-2);
}
#_eli3_help_recovery_btns .btn-action {
  flex: 0 0 auto;
  text-align: center;
}

/* Contact tab — kv table */
._eli3_kv_row {
  display: grid;
  grid-template-columns: 110px 1fr;
  gap: var(--space-3);
  padding: 6px 0;
  border-bottom: 1px solid #f1f5f9;
  font-size: 12px;
}
._eli3_kv_row:last-child { border-bottom: none; }
._eli3_kv_label {
  font-weight: var(--weight-bold);
  color: var(--text-status-footer);
}
._eli3_kv_value {
  flex: 1;
  font-family: var(--font-mono);
  word-break: break-all;
  color: var(--text-on-light);
}

/* Console tab — toolbar + log list */
._eli3_console_toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
  align-items: center;
  padding: 6px var(--space-2);
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_filter_btn {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_filter_btn:hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_filter_btn_active {
  background: linear-gradient(135deg, var(--color-blue) 0%, var(--color-blue-deep) 100%);
  color: #fff;
  border-color: var(--color-blue-deep);
}
._eli3_filter_btn_active:hover {
  background: linear-gradient(135deg, #1976d2 0%, var(--color-blue) 100%);
  color: #fff;
  border-color: var(--color-blue);
}
/* Copy + Clear buttons in the console toolbar — same platinum treatment */
._eli3_console_toolbar button:not(._eli3_filter_btn) {
  padding: 4px 10px;
  font: var(--weight-bold) var(--font-xs)/1 var(--font-family);
  letter-spacing: 0.3px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  border: 1px solid #b0bec5;
  color: var(--text-status-footer);
  cursor: pointer;
  transition: all .15s ease;
}
._eli3_console_toolbar button:not(._eli3_filter_btn):hover {
  background: linear-gradient(to bottom, #ffffff 0%, #e3f2fd 100%);
  border-color: #90caf9;
  color: var(--color-blue);
}
._eli3_console_meta {
  margin-left: auto;
  font: var(--weight-semibold) var(--font-sm)/1 var(--font-family);
  color: var(--text-dim);
}
._eli3_log_list {
  max-height: 360px;
  overflow-y: auto;
  border: 1px solid #e2e8f0;
}
._eli3_log_row {
  display: flex;
  gap: 6px;
  padding: var(--space-1) var(--space-2);
  border-bottom: 1px solid #f1f5f9;
  font: var(--font-md)/1.4 var(--font-mono);
  flex-wrap: wrap;
}
._eli3_log_time { color: var(--text-dim); flex-shrink: 0; }
._eli3_log_chan {
  color: var(--color-blue);
  font-weight: var(--weight-bold);
  flex-shrink: 0;
  min-width: 50px;
}
._eli3_log_msg { flex: 1; color: var(--text-on-light); }
._eli3_log_payload {
  width: 100%;
  margin-top: 2px;
  padding-left: 56px;
  font-size: var(--font-sm);
  color: var(--text-status-footer);
  word-break: break-all;
}
._eli3_log_empty {
  padding: var(--space-3);
  text-align: center;
  font-style: italic;
  color: var(--text-dim);
  font-size: var(--font-md);
}

/* ─── 2026-05-13 rewrite — Help / About surfaces ──────────────────
 *   Premium card treatment shared by Ask AI, Submit Feedback, and
 *   Announcements blocks. About uses a hero + stat grid (no buttons).
 */
._eli3_dialog_tabbed_v2 .eli-dialog-desc { padding-top: 4px; }

._eli3_help_card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 12px 14px;
  margin-bottom: 12px;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.04);
}
._eli3_help_card:last-child { margin-bottom: 0; }
._eli3_help_card_head {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-bottom: 10px;
}
._eli3_help_card_icon {
  flex: 0 0 auto;
  width: 28px; height: 28px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px;
  background: linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%);
  border: 1px solid #cbd5e1;
  border-radius: 6px;
}
._eli3_help_card_titles { flex: 1 1 auto; min-width: 0; }
._eli3_help_card_title {
  font: 800 12.5px/1.2 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_help_card_sub {
  font: 500 11px/1.45 'Inter', sans-serif;
  color: #64748b;
  margin-top: 2px;
}

/* ── Ask AI ── */
._eli3_help_ask_input {
  width: 100%;
  padding: 8px 10px;
  font: 500 12px/1.45 'Inter', sans-serif;
  color: #0f172a;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  outline: none;
  resize: vertical;
  box-sizing: border-box;
  transition: border-color .12s, background .12s;
}
._eli3_help_ask_input:focus {
  border-color: #1565c0;
  background: #fff;
}
._eli3_help_ask_row {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 8px;
}
._eli3_help_ask_hint {
  font: 500 10.5px/1 'Inter', sans-serif;
  color: #94a3b8;
}
._eli3_help_ask_answer {
  margin-top: 12px;
  padding: 10px 12px;
  background: linear-gradient(135deg, #f8fafc 0%, #f1f5f9 100%);
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._eli3_help_ask_answer_text {
  font: 500 12px/1.55 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_help_ask_answer_text p { margin: 0 0 8px; }
._eli3_help_ask_answer_text p:last-child { margin-bottom: 0; }
._eli3_help_ask_pending {
  font: 500 11.5px/1.5 'Inter', sans-serif;
  color: #64748b;
}
._eli3_help_ask_err {
  font: 600 11.5px/1.5 'Inter', sans-serif;
  color: #b91c1c;
}

/* ── Shared buttons inside Help cards ── */
._eli3_help_btn_primary {
  padding: 7px 16px;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_btn_primary:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
}
._eli3_help_btn_primary:disabled { opacity: 0.55; cursor: progress; }
._eli3_help_btn_ghost {
  padding: 7px 14px;
  font: 700 11px/1 'Inter', sans-serif;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #b0bec5;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_btn_ghost:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}

/* ── Submit feedback ── */
._eli3_help_typerow {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}
._eli3_help_typetile {
  flex: 1 1 0;
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 8px 10px;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font: 700 11.5px/1 'Inter', sans-serif;
  color: #475569;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_typetile input { display: none; }
._eli3_help_typetile:hover { border-color: #93c5fd; color: #1565c0; }
._eli3_help_typetile_active {
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border-color: #1565c0;
  color: #0d47a1;
  box-shadow: inset 0 0 0 1px #1565c0;
}
._eli3_help_fb_title,
._eli3_help_fb_body {
  width: 100%;
  padding: 8px 10px;
  margin-bottom: 8px;
  font: 500 12px/1.45 'Inter', sans-serif;
  color: #0f172a;
  background: #f8fafc;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  outline: none;
  box-sizing: border-box;
  transition: border-color .12s, background .12s;
}
._eli3_help_fb_body { resize: vertical; min-height: 60px; }
._eli3_help_fb_title:focus,
._eli3_help_fb_body:focus {
  border-color: #1565c0;
  background: #fff;
}
._eli3_help_fb_actions {
  display: flex;
  gap: 8px;
  align-items: center;
}
._eli3_help_fb_status {
  margin-top: 8px;
  font: 600 11px/1.4 'Inter', sans-serif;
  min-height: 16px;
}
._eli3_help_fb_status_ok       { color: #15803d; }
._eli3_help_fb_status_warn     { color: #b45309; }
._eli3_help_fb_status_err      { color: #b91c1c; }
._eli3_help_fb_status_pending  { color: #64748b; font-style: italic; }

/* ── Announcements list ── */
._eli3_help_announce_list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
._eli3_help_announce_empty {
  padding: 16px;
  text-align: center;
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
}
._eli3_help_announce_row {
  display: flex;
  gap: 10px;
  padding: 9px 11px;
  background: #fafbfc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  cursor: pointer;
  transition: all .12s;
}
._eli3_help_announce_row:hover {
  border-color: #93c5fd;
  background: #f0f9ff;
}
._eli3_help_announce_new {
  border-left: 3px solid #1565c0;
  background: linear-gradient(135deg, #eff6ff 0%, #f8fafc 100%);
}
._eli3_help_announce_icon {
  flex: 0 0 auto;
  width: 24px; height: 24px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 14px;
}
._eli3_help_announce_meta { flex: 1 1 auto; min-width: 0; }
._eli3_help_announce_title {
  font: 700 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_help_announce_newbadge {
  display: inline-block;
  margin-left: 6px;
  padding: 1px 6px;
  font: 800 8.5px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  color: #fff;
  background: #1565c0;
  border-radius: 3px;
  vertical-align: middle;
}
._eli3_help_announce_sum {
  font: 500 11px/1.45 'Inter', sans-serif;
  color: #475569;
  margin-top: 2px;
}
._eli3_help_announce_footer {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-top: 4px;
}
._eli3_help_announce_status {
  font: 800 8.5px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 2px 6px;
  border-radius: 3px;
}
._eli3_status_open       { background: #fef3c7; color: #92400e; }
._eli3_status_inprogress { background: #dbeafe; color: #1e40af; }
._eli3_status_fixed,
._eli3_status_shipped    { background: #dcfce7; color: #166534; }
._eli3_status_wontfix    { background: #f1f5f9; color: #64748b; }
._eli3_help_announce_time {
  font: 500 10px/1 'Inter', sans-serif;
  color: #94a3b8;
}

/* ─── About tab — hero + credit + stats, no buttons ──────────────── */
._eli3_about_root {
  padding: 4px 2px 8px;
  text-align: center;
}
._eli3_about_hero {
  display: flex; align-items: center; justify-content: center; gap: 14px;
  margin-bottom: 14px;
}
._eli3_about_logo {
  width: 64px; height: 64px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 36px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #c9a227;
  border: 2px solid #c9a227;
  border-radius: 14px;
  box-shadow: 0 4px 12px rgba(15, 23, 42, 0.18);
}
._eli3_about_brand { text-align: left; }
._eli3_about_brand_name {
  font: 800 28px/1 'Book Antiqua', Georgia, serif;
  color: #0d1b2a;
  letter-spacing: 1px;
}
._eli3_about_brand_tag {
  font: 600 11px/1 'Inter', sans-serif;
  color: #c9a227;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-top: 4px;
}
._eli3_about_lead {
  font: 500 12px/1.55 'Inter', sans-serif;
  color: #475569;
  max-width: 460px;
  margin: 0 auto 16px;
}
._eli3_about_credit {
  padding: 12px 16px;
  margin: 0 auto 14px;
  max-width: 320px;
  background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
  border: 1px solid #fcd34d;
  border-radius: 8px;
}
._eli3_about_credit_eyebrow {
  font: 800 9px/1 'Inter', sans-serif;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #92400e;
}
._eli3_about_credit_name {
  font: 800 16px/1.1 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 4px;
}
._eli3_about_stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}
._eli3_about_stat {
  padding: 8px 10px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
}
._eli3_about_stat_label {
  font: 700 9px/1 'Inter', sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: #94a3b8;
}
._eli3_about_stat_value {
  font: 700 13px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 4px;
}
._eli3_about_userblock {
  padding: 10px 14px;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  display: inline-block;
  text-align: left;
  min-width: 240px;
}
._eli3_about_user_line {
  font: 700 12.5px/1.2 'Inter', sans-serif;
  color: #0f172a;
  margin-top: 3px;
}
._eli3_about_user_sub {
  font: 500 11px/1.3 'Inter', sans-serif;
  color: #64748b;
  margin-top: 2px;
}
